* Control Block for Measurements
.control
  op
  let p_diss = -i(VDD) * 1.8
  print p_diss

  * AC Analysis for Closed-Loop and Open-Loop Characteristics
  ac dec 50 100 1G
  let acl_db = vdb(Vout) - vdb(Vin)
  meas ac cl_gain_dc find acl_db at=1k
  meas ac closed_loop_bw when acl_db = (cl_gain_dc - 3.0) fall=1

  * Open-loop loop-gain estimation using diff-amp input node vm
  let loop_gain_db = vdb(Vout) - vdb(vm)
  let loop_phase = 180 + (180/PI * cph(v(Vout)/v(vm)))
  meas ac open_loop_gain_dc find loop_gain_db at=1k
  meas ac fun when loop_gain_db = 0 fall=1
  meas ac phase_margin find loop_phase when loop_gain_db = 0 fall=1

  * Transient Analysis for Step Response, Slewing and Settling
  tran 0.1n 600n 500n
  meas tran v_init find v(Vout) at=500.5n
  meas tran v_final find v(Vout) at=539.0n
  meas tran sr_rise trig v(Vout) val=0.6 rise=1 targ v(Vout) val=1.2 rise=1
  meas tran sr_fall trig v(Vout) val=1.2 fall=1 targ v(Vout) val=0.6 fall=1

  quit
.endc
.end

